Then, for any $\boldsymbol{x}\in{\mathbb R}^3$, the observed complex GRE signal $I(\boldsymbol{x},TE)$ at an echo time $TE\mathrm{sec}$ is modeled as
\begin{align}\label{ComplexMR}
I(\boldsymbol{x},TE)=m(\boldsymbol{x})\exp\left\{-i\left(b(\boldsymbol{x})\omega_0B_0TE+\theta_0(\boldsymbol{x})\right)\right\},
\end{align}
where $\omega_0=42.577 \mathrm{MHz/T}$ is the proton gyromagnetic ratio, $b$ is the total field induced by the susceptibility distribution in an MR scanner, and $\theta_0$ is the coil sensitivity dependent phase offset.

\begin{align}\label{ComplexMR}
I(\boldsymbol{x},TE)=m(\boldsymbol{x})\exp\left\{-i\left(b(\boldsymbol{x})\omega_0B_0TE+\theta_0(\boldsymbol{x})\right)\right\},
\end{align}

\begin{align}\label{phasemodel}
\theta(\boldsymbol{x})=b(\boldsymbol{x})\omega_0B_0TE+\theta_0(\boldsymbol{x}).
\end{align}

Given the local field $b_l$, the dipole inversion recovers the susceptibility distribution $\chi$ in $\Omega$ by solving the following convolution relation \cite{T.Liu2011,T.Liu2011a,T.Liu2009}:
\begin{align}\label{QSM_Deconv}
b_l(\boldsymbol{x})=\mathrm{pv}\int_{\Omega}d(\boldsymbol{x}-{\boldsymbol y})\chi({\boldsymbol y})\mathrm{d}{\boldsymbol y},
\end{align}
where $\mathrm{pv}$ denotes the principal value \cite{E.M.Stein2011} of the singular integral with the kernel $d$:
\begin{align*}
d(\boldsymbol{x})=\frac{2x_3^2-x_1^2-x_2^2}{4\pi|\boldsymbol{x}|^5}.
\end{align*}

\begin{align}\label{QSM_Deconv}
b_l(\boldsymbol{x})=\mathrm{pv}\int_{\Omega}d(\boldsymbol{x}-{\boldsymbol y})\chi({\boldsymbol y})\mathrm{d}{\boldsymbol y},
\end{align}

\begin{align*}
d(\boldsymbol{x})=\frac{2x_3^2-x_1^2-x_2^2}{4\pi|\boldsymbol{x}|^5}.
\end{align*}

In the frequency domain, \cref{QSM_Deconv} reads
\begin{align}\label{QSM_Fou}
{\mathscr F}(b_l)({\boldsymbol{\xi}})={\mathcal D}({\boldsymbol{\xi}}){\mathscr F}(\chi)({\boldsymbol{\xi}})=\left(\frac{1}{3}-\frac{\xi_3^2}{|{\boldsymbol{\xi}}|^2}\right){\mathscr F}(\chi)({\boldsymbol{\xi}})
\end{align}
where ${\mathcal D}={\mathscr F}(d)$ is the Fourier transform of $d$ and ${\mathcal D}(\0)=0$  by the definition of $\mathrm{pv}$ \cite{L.deRochefort2010,E.M.Haacke2015}.

\begin{align}\label{QSM_Fou}
{\mathscr F}(b_l)({\boldsymbol{\xi}})={\mathcal D}({\boldsymbol{\xi}}){\mathscr F}(\chi)({\boldsymbol{\xi}})=\left(\frac{1}{3}-\frac{\xi_3^2}{|{\boldsymbol{\xi}}|^2}\right){\mathscr F}(\chi)({\boldsymbol{\xi}})
\end{align}

One benchmark method, called the truncated K-space division (TKD) \cite{K.Shmueli2009}, finds the approximate solution to \cref{QSM_Fou} via:
\begin{align}\label{TKD}
\chi_{\hbar}={\mathscr F}^{-1}({\mathcal X}_{\hbar}),~~~\text{where}~~{\mathcal X}_{\hbar}({\boldsymbol{\xi}})=\frac{\mathrm{sign}({\mathcal D}({\boldsymbol{\xi}}))}{\max\left\{|{\mathcal D}({\boldsymbol{\xi}})|,\hbar\right\}}{\mathscr F}(b_l)({\boldsymbol{\xi}})




\end{align}
with a threshold level $\hbar>0$.

\begin{align}\label{TKD}
\chi_{\hbar}={\mathscr F}^{-1}({\mathcal X}_{\hbar}),~~~\text{where}~~{\mathcal X}_{\hbar}({\boldsymbol{\xi}})=\frac{\mathrm{sign}({\mathcal D}({\boldsymbol{\xi}}))}{\max\left\{|{\mathcal D}({\boldsymbol{\xi}})|,\hbar\right\}}{\mathscr F}(b_l)({\boldsymbol{\xi}})




\end{align}

Another method recovers $\chi$ via solving the following Tikhonov regularization \cite{B.Kressler2010}:
\begin{align}\label{Tikhonov}

\min_{\chi}~\frac{1}{2}\left\|A\chi-b_l\right\|_2^2+\varepsilon\left\|\chi\right\|_2^2
\end{align}
where $\varepsilon>0$ and $A$ denotes the forward operator that is obtained by discretizing the kernel ${\mathcal D}$.

\begin{align}\label{Tikhonov}

\min_{\chi}~\frac{1}{2}\left\|A\chi-b_l\right\|_2^2+\varepsilon\left\|\chi\right\|_2^2
\end{align}

Mathematically, it is formulated as solving the minimization problem:
\begin{align}\label{Regularization}
\min_{\chi}~F(b_l|\chi)+R(\chi),
\end{align}
where $F(b_l|\chi)$ denotes the data fidelity term and $R(\chi)$ is the regularization term which mostly promotes the sparse approximation of $\chi$ under some linear transformation such as total variation and wavelet frames.

\begin{align}\label{Regularization}
\min_{\chi}~F(b_l|\chi)+R(\chi),
\end{align}

\begin{align}\label{QSM_PDE}
-\Delta b_l(\boldsymbol{x})=P(D)\chi(\boldsymbol{x})=\left(-\frac{1}{3}\Delta+\frac{\partial^2}{\partial x_3^2}\right)\chi(\boldsymbol{x})~~~~~~~\boldsymbol{x}\in\Omega
\end{align}

In \cite{Y.Kee2017}, the differential approach is implemented by incorporating the spherical mean value (SMV) filter $S_r$ with a radius $r>0$ \cite{W.Li2014} into the integral approach:
\begin{align}\label{IntegralSMV}
\min_{\chi}~\frac{1}{2}\left\|S_r\left(A\chi-b_l\right)\right\|_2^2+R(\chi).
\end{align}

\begin{align}\label{IntegralSMV}
\min_{\chi}~\frac{1}{2}\left\|S_r\left(A\chi-b_l\right)\right\|_2^2+R(\chi).
\end{align}

This magnetization generates a macroscopic field $\mathbf{B}(\boldsymbol{x})$ satisfying the following magnetostatic Maxwell's equation \cite{E.M.Haacke1999,J.K.Seo2014}
\begin{align}\label{MagnetostaticMaxwell}
\begin{split}
\nabla\cdot\mathbf{B}&=0\\
\nabla\times\mathbf{B}&=\mu_0\nabla\times{\mathbf M},
\end{split}
\end{align}
where $\mu_0=8.854\times 10^{-12} \mathrm{F/m}$ is the vacuum permittivity.

\begin{align}\label{MagnetostaticMaxwell}
\begin{split}
\nabla\cdot\mathbf{B}&=0\\
\nabla\times\mathbf{B}&=\mu_0\nabla\times{\mathbf M},
\end{split}
\end{align}

Since the MRI signal is generated by the microscopic field $\mathbf{B}_{\ell}(\boldsymbol{x})$ experienced by the spins of water protons \cite{Y.Kee2017}, we use the following Lorenz sphere correction model \cite{E.M.Haacke1999}:
\begin{align}\label{Lorenz}
\mathbf{B}_{\ell}(\boldsymbol{x})=\mathbf{B}(\boldsymbol{x})-\frac{2}{3}\mu_0{\mathbf M}(\boldsymbol{x})
\end{align}
to relate $\mathbf{B}(\boldsymbol{x})$ and $\mathbf{B}_{\ell}(\boldsymbol{x})$.

\begin{align}\label{Lorenz}
\mathbf{B}_{\ell}(\boldsymbol{x})=\mathbf{B}(\boldsymbol{x})-\frac{2}{3}\mu_0{\mathbf M}(\boldsymbol{x})
\end{align}

Moreover, since we consider the linear magnetic materials with $|\chi|\ll1$, $\chi$ can be approximated as
\begin{align}\label{Approx1}
\chi(\boldsymbol{x})\approx\frac{\mu_0}{B_0}{\mathbf M}(\boldsymbol{x}).
\end{align}

\begin{align}\label{Approx1}
\chi(\boldsymbol{x})\approx\frac{\mu_0}{B_0}{\mathbf M}(\boldsymbol{x}).
\end{align}

Finally, we introduce the total field $b(\boldsymbol{x})$ as
\begin{align}\label{Approx2}
b(\boldsymbol{x})=\frac{B_{\ell3}(\boldsymbol{x})-B_0}{B_0}
\end{align}
where $B_{\ell3}(\boldsymbol{x})$ denotes the third component of $\mathbf{B}_{\ell}(\boldsymbol{x})$.

\begin{align}\label{Approx2}
b(\boldsymbol{x})=\frac{B_{\ell3}(\boldsymbol{x})-B_0}{B_0}
\end{align}

Combining \cref{MagnetostaticMaxwell,Lorenz,Approx1,Approx2} and taking the third component into account only, we obtain the following relation between $\chi$ and $b$ in the frequency domain:
\begin{align}\label{QSM_Fou2}
|{\boldsymbol{\xi}}|^2{\mathscr F}(b)({\boldsymbol{\xi}})=\left(\frac{1}{3}|{\boldsymbol{\xi}}|^2-\xi_3^2\right){\mathscr F}(\chi)({\boldsymbol{\xi}}),
\end{align}
which gives
\begin{align}\label{QSM_PDE2}
-\Delta b=P(D)\chi:=\left(-\frac{1}{3}\Delta+\frac{\partial^2}{\partial x_3^2}\right)\chi.
\end{align}

\begin{align}\label{QSM_Fou2}
|{\boldsymbol{\xi}}|^2{\mathscr F}(b)({\boldsymbol{\xi}})=\left(\frac{1}{3}|{\boldsymbol{\xi}}|^2-\xi_3^2\right){\mathscr F}(\chi)({\boldsymbol{\xi}}),
\end{align}

\begin{align}\label{QSM_PDE2}
-\Delta b=P(D)\chi:=\left(-\frac{1}{3}\Delta+\frac{\partial^2}{\partial x_3^2}\right)\chi.
\end{align}

Then for a given susceptibility distribution $\chi$ (in ${\mathbb R}^3$), the general solution $b$ which is bounded everywhere in ${\mathbb R}^3$ is expressed as
\begin{align}\label{GeneralSolution}
b(\boldsymbol{x})=\int_{{\mathbb R}^3}\Phi(\boldsymbol{x}-{\boldsymbol y})\left(-\frac{1}{3}\Delta_{{\boldsymbol y}}+\frac{\partial^2}{\partial y_3^2}\right)\chi({\boldsymbol y})\mathrm{d}{\boldsymbol y}+b_0
\end{align}
where $b_0$ is some constant, and $\Phi(\boldsymbol{x})=1/\left(4\pi|\boldsymbol{x}|\right)$.

\begin{align}\label{GeneralSolution}
b(\boldsymbol{x})=\int_{{\mathbb R}^3}\Phi(\boldsymbol{x}-{\boldsymbol y})\left(-\frac{1}{3}\Delta_{{\boldsymbol y}}+\frac{\partial^2}{\partial y_3^2}\right)\chi({\boldsymbol y})\mathrm{d}{\boldsymbol y}+b_0
\end{align}

However, since we can remove it during the phase estimation from the multi echo GRE signal \cite{L.deRochefort2008}, we assume that $b_0=0$ and
\begin{align}\label{Forward1}
b(\boldsymbol{x})=\int_{{\mathbb R}^3}\Phi(\boldsymbol{x}-{\boldsymbol y})\left(-\frac{1}{3}\Delta_{{\boldsymbol y}}+\frac{\partial^2}{\partial y_3^2}\right)\chi({\boldsymbol y})\mathrm{d}{\boldsymbol y}
\end{align}
in the rest of this paper.

\begin{align}\label{Forward1}
b(\boldsymbol{x})=\int_{{\mathbb R}^3}\Phi(\boldsymbol{x}-{\boldsymbol y})\left(-\frac{1}{3}\Delta_{{\boldsymbol y}}+\frac{\partial^2}{\partial y_3^2}\right)\chi({\boldsymbol y})\mathrm{d}{\boldsymbol y}
\end{align}

\label{RK211}
Since \cite[Proposition A.1.]{J.K.Choi2014} has discussed the equivalence between \cref{Forward1} and the following representation in the literature
\begin{align}\label{Forward_Convention}
b(\boldsymbol{x})=\mathrm{pv}\int_{{\mathbb R}^3}d(\boldsymbol{x}-{\boldsymbol y})\chi({\boldsymbol y})\mathrm{d}{\boldsymbol y},
\end{align}
we shall use \cref{Forward1} in the rest of this paper. Note that \cref{Forward1} avoids the singularity of the kernel $d(\boldsymbol{x}-{\boldsymbol y})$ in \cref{Forward_Convention} as $\Phi(\boldsymbol{x}-{\boldsymbol y})$ is locally integrable near $\boldsymbol{x}={\boldsymbol y}$.

\begin{align}\label{Forward_Convention}
b(\boldsymbol{x})=\mathrm{pv}\int_{{\mathbb R}^3}d(\boldsymbol{x}-{\boldsymbol y})\chi({\boldsymbol y})\mathrm{d}{\boldsymbol y},
\end{align}

In the literature, given that the background field is harmonic in $\Omega$ \cite{Y.Wang2015,D.Zhou2014}, the background field removal methods take the form of the following Poisson's equation in \cite{D.Zhou2014}:
\begin{align}\label{LBV}
\left\{\begin{array}{rcll}
-\Delta b_l\hspace{-0.65em}&=\hspace{-0.65em}&-\Delta b&\text{in}~\Omega \vspace{0.125em}\\
b_l\hspace{-0.65em}&=\hspace{-0.65em}&0&\text{on}~\partial\Omega.
\end{array}\right.
\end{align}

\begin{align}\label{LBV}
\left\{\begin{array}{rcll}
-\Delta b_l\hspace{-0.65em}&=\hspace{-0.65em}&-\Delta b&\text{in}~\Omega \vspace{0.125em}\\
b_l\hspace{-0.65em}&=\hspace{-0.65em}&0&\text{on}~\partial\Omega.
\end{array}\right.
\end{align}

\begin{align}\label{NewModeling}
b_l(\boldsymbol{x})=\int_{\Omega}\Phi(\boldsymbol{x}-{\boldsymbol y})\left(-\frac{1}{3}\Delta_{{\boldsymbol y}}+\frac{\partial^2}{\partial y_3^2}\right)\chi({\boldsymbol y})\mathrm{d}{\boldsymbol y}+v(\boldsymbol{x})
\end{align}

\begin{align}\label{DistLapIncompatibility}
\int_{{\mathbb R}^3}v(\boldsymbol{x})\left(-\Delta\varphi\right)(\boldsymbol{x})\mathrm{d}\boldsymbol{x}=\int_{\partial\Omega}\left[\frac{\partial v_{\mathrm i}}{\partial\boldsymbol{n}}(\boldsymbol{x})-\frac{\partial v_{\mathrm e}}{\partial\boldsymbol{n}}(\boldsymbol{x})\right]\varphi(\boldsymbol{x})\mathrm{d}\boldsymbol{\sigma}(\boldsymbol{x})
\end{align}

\begin{align}\label{NonVanishingSurfMeas}
\frac{\partial v_{\mathrm i}}{\partial\boldsymbol{n}}-\frac{\partial v_{\mathrm e}}{\partial\boldsymbol{n}}\neq0~~~~\text{almost everywhere on}~\partial\Omega
\end{align}

 Since $-\Delta b=P(D)\chi$, the governing equation in \cref{LBV} becomes
\begin{align*}
\left\{\begin{array}{rcll}
-\Delta b_l\hspace{-0.65em}&=\hspace{-0.65em}&P(D)\chi&\text{in}~\Omega \vspace{0.125em}\\
b_l\hspace{-0.65em}&=\hspace{-0.65em}&0&\text{on}~\partial\Omega.
\end{array}\right.
\end{align*}
Let $G(\boldsymbol{x},{\boldsymbol y})$ denote the Green's function in $\Omega$:
\begin{align*}
G(\boldsymbol{x},{\boldsymbol y})=\Phi({\boldsymbol y}-\boldsymbol{x})-H(\boldsymbol{x},{\boldsymbol y})
\end{align*}
where for each $\boldsymbol{x}\in\Omega$, the corrector function $H(\boldsymbol{x},{\boldsymbol y})$ satisfies
\begin{align*}
\left\{\begin{array}{rclll}
-\Delta_{{\boldsymbol y}} H(\boldsymbol{x},{\boldsymbol y})\hspace{-0.65em}&=\hspace{-0.65em}&0&\text{if}&{\boldsymbol y}\in\Omega \vspace{0.125em}\\
H(\boldsymbol{x},{\boldsymbol y})\hspace{-0.65em}&=\hspace{-0.65em}&\Phi({\boldsymbol y}-\boldsymbol{x})&\text{if}&{\boldsymbol y}\in\partial\Omega.
\end{array}\right.
\end{align*}
Note that since $G(\boldsymbol{x},{\boldsymbol y})=G({\boldsymbol y},\boldsymbol{x})$ for $\boldsymbol{x},{\boldsymbol y}\in\Omega$ and $\Phi({\boldsymbol y}-\boldsymbol{x})=\Phi(\boldsymbol{x}-{\boldsymbol y})$, we have $H(\boldsymbol{x},{\boldsymbol y})=H({\boldsymbol y},\boldsymbol{x})$ for $\boldsymbol{x},{\boldsymbol y}\in\Omega$. Consequently, we have
\begin{align}\label{CorrectorHarmonicSym}
-\Delta_{\boldsymbol{x}}H(\boldsymbol{x},{\boldsymbol y})=-\Delta_{\boldsymbol{x}}H({\boldsymbol y},\boldsymbol{x})=0~~~~~\boldsymbol{x}\in\Omega.
\end{align}
Then the solution to \cref{LBV} is represented as
\begin{align*}
b_l(\boldsymbol{x})=\int_{\Omega}G(\boldsymbol{x},{\boldsymbol y})P(D_{{\boldsymbol y}})\chi({\boldsymbol y})\mathrm{d}{\boldsymbol y}=\int_{\Omega}\Phi(\boldsymbol{x}-{\boldsymbol y})P(D_{{\boldsymbol y}})\chi({\boldsymbol y})\mathrm{d}{\boldsymbol y}+{\mathcal H}(\boldsymbol{x})
\end{align*}
where we used the fact that $\Phi({\boldsymbol y}-\boldsymbol{x})=\Phi(\boldsymbol{x}-{\boldsymbol y})$, and ${\mathcal H}(\boldsymbol{x})$ is defined as
\begin{align*}\label{HarmonicInterior}
{\mathcal H}(\boldsymbol{x})=-\int_{\Omega}H(\boldsymbol{x},{\boldsymbol y})P(D_{{\boldsymbol y}})\chi({\boldsymbol y})\mathrm{d}{\boldsymbol y}
\end{align*}
for $\boldsymbol{x}\in\Omega$. Then we can see that ${\mathcal H}(\boldsymbol{x})$ satisfies
\begin{align}\label{H_HarmonicEq}
\left\{\begin{array}{rcll}
-\Delta{\mathcal H}\hspace{-0.65em}&=\hspace{-0.65em}&0&\text{in}~\Omega \vspace{0.125em}\\
{\mathcal H}\hspace{-0.65em}&=\hspace{-0.65em}&-\widetilde{b}_l&\text{on}~\partial\Omega
\end{array}\right.
\end{align}
where the first equation of \cref{H_HarmonicEq} comes from \cref{CorrectorHarmonicSym}. Here, $\widetilde{b}_l$ is induced by the information of $\chi$ only in $\Omega$:
\begin{align}\label{TrueLocalField}
\widetilde{b}_l(\boldsymbol{x})=\int_{\Omega}\Phi(\boldsymbol{x}-{\boldsymbol y})P(D_{{\boldsymbol y}})\chi({\boldsymbol y})\mathrm{d}{\boldsymbol y}=\int_{{\mathbb R}^3}\Phi(\boldsymbol{x}-{\boldsymbol y})1_{\Omega}({\boldsymbol y})P(D_{{\boldsymbol y}})\chi({\boldsymbol y})\mathrm{d}{\boldsymbol y}
\end{align}
with $1_{\Omega}$ being the characteristic function of $\Omega$.
























Based on the fact that $b_l(\boldsymbol{x})=0$ for $\boldsymbol{x}\in{\mathbb R}^3\setminus\overline{\Omega}$, we define
\begin{align*}
v(\boldsymbol{x})=\left\{\begin{array}{cccll}
v_{\mathrm i}(\boldsymbol{x})\hspace{-0.65em}&=\hspace{-0.65em}&{\mathcal H}(\boldsymbol{x})&\text{if}&\boldsymbol{x}\in\Omega \vspace{0.125em}\\
v_{\mathrm e}(\boldsymbol{x})\hspace{-0.65em}&=\hspace{-0.65em}&-\widetilde{b}_l(\boldsymbol{x})&\text{if}&\boldsymbol{x}\notin\Omega.
\end{array}\right.
\end{align*}
Hence, we obtain \cref{NewModeling}, and we can further see that $v_{\mathrm i}$ and $v_{\mathrm e}$ satisfy
\begin{align}
-\Delta v_{\mathrm i}&=0~~~~~~\text{in }  \Omega \label{v_iharmonic}\\
-\Delta v_{\mathrm e}&=0~~~~~~\text{in }  {\mathbb R}^3\setminus\overline{\Omega} \label{v_eharmonic}\\
v_{\mathrm i}=v_{\mathrm e}&=-\widetilde{b}_l~~~\text{on } \partial\Omega, \label{vboundaryconti}
\end{align}
respectively, where \cref{v_eharmonic} comes from \cref{TrueLocalField}; $-\Delta\widetilde{b}_l=1_{\Omega}P(D)\chi$, i.e. $-\Delta\widetilde{b}_l=P(D)\chi$ in $\Omega$, and $-\Delta\widetilde{b}_l=0$ in ${\mathbb R}^3\setminus\overline{\Omega}$.

To prove \cref{DistLapIncompatibility}, let $\varphi\in C_0^{\infty}({\mathbb R}^3)$, and we consider
\begin{align*}
\int_{{\mathbb R}^3}v(\boldsymbol{x})\left(-\Delta\varphi\right)(\boldsymbol{x})\mathrm{d}\boldsymbol{x}&=\int_{\Omega}v_{\mathrm i}(\boldsymbol{x})\left(-\Delta\varphi\right)(\boldsymbol{x})\mathrm{d}\boldsymbol{x}+\int_{{\mathbb R}^3\setminus\overline{\Omega}}v_{\mathrm e}(\boldsymbol{x})\left(-\Delta\varphi\right)(\boldsymbol{x})\mathrm{d}\boldsymbol{x}\\
&=I_1+I_2
\end{align*}
Using \cref{v_iharmonic,vboundaryconti} and the Green's identity (e.g. \cite{Evans2010}), we have
\begin{align*}
I_1&=\int_{\Omega}\left[\varphi(\boldsymbol{x})\left(\Delta v_{\mathrm i}\right)(\boldsymbol{x})-v_{\mathrm i}(\boldsymbol{x})\left(\Delta\varphi\right)(\boldsymbol{x})\right]\mathrm{d}\boldsymbol{x}\\
&=\int_{\partial\Omega}\left[\varphi(\boldsymbol{x})\frac{\partial v_{\mathrm i}}{\partial\boldsymbol{n}}(\boldsymbol{x})-v_{\mathrm i}(\boldsymbol{x})\frac{\partial\varphi}{\partial\boldsymbol{n}}(\boldsymbol{x})\right]\mathrm{d}\boldsymbol{\sigma}(\boldsymbol{x})=\int_{\partial\Omega}\left[\varphi(\boldsymbol{x})\frac{\partial v_{\mathrm i}}{\partial\boldsymbol{n}}(\boldsymbol{x})+\widetilde{b}_l(\boldsymbol{x})\frac{\partial\varphi}{\partial\boldsymbol{n}}(\boldsymbol{x})\right]\mathrm{d}\boldsymbol{\sigma}(\boldsymbol{x}).
\end{align*}
Similarly using \cref{v_eharmonic,vboundaryconti}, we also have
\begin{align*}
I_2&=\int_{{\mathbb R}^3\setminus\overline{\Omega}}\left[\varphi(\boldsymbol{x})\left(\Delta v_{\mathrm e}\right)(\boldsymbol{x})-v_{\mathrm e}(\boldsymbol{x})\left(\Delta\varphi\right)(\boldsymbol{x})\right]\mathrm{d}\boldsymbol{x}\\
&=\int_{\partial\Omega}\left[-\varphi(\boldsymbol{x})\frac{\partial v_{\mathrm e}}{\partial\boldsymbol{n}}(\boldsymbol{x})+v_{\mathrm e}(\boldsymbol{x})\frac{\partial\varphi}{\partial\boldsymbol{n}}(\boldsymbol{x})\right]\mathrm{d}\boldsymbol{\sigma}(\boldsymbol{x})=-\int_{\partial\Omega}\left[\varphi(\boldsymbol{x})\frac{\partial v_{\mathrm e}}{\partial\boldsymbol{n}}(\boldsymbol{x})+\widetilde{b}_l(\boldsymbol{x})\frac{\partial\varphi}{\partial\boldsymbol{n}}(\boldsymbol{x})\right]\mathrm{d}\boldsymbol{\sigma}(\boldsymbol{x})
\end{align*}
where the second equality comes from the fact that we need to compute the inward normal derivatives on $\partial\Omega$. Hence, combining these two equalities, we obtain \cref{DistLapIncompatibility}.

To prove 2, we assume on the contrary that there exists $\boldsymbol{x}\in\partial\Omega$ such that
\begin{align*}
\frac{\partial v_{\mathrm i}}{\partial\boldsymbol{n}}=\frac{\partial v_{\mathrm e}}{\partial\boldsymbol{n}}
\end{align*}
for some open and connected set $U\subseteq\partial\Omega$ such that $\boldsymbol{x}\in U$ and $\boldsymbol{\sigma}(U)>0$. Choose $r>0$ such that $B(\boldsymbol{x},r)\cap\partial\Omega$ is contained in $U$, where $B(\boldsymbol{x},r)$ denotes an open ball centered at $\boldsymbol{x}$ with radius $r$. Then since $-\Delta v=0$ in $B(\boldsymbol{x},r)$ and $v=v_{\mathrm e}=-\widetilde{b}_l$ in $B(\boldsymbol{x},r)\cap\left({\mathbb R}^3\setminus\overline{\Omega}\right)$, it follows that $v=-\widetilde{b}_l$ in $B(\boldsymbol{x},r)$ by the analyticity of $v$ in $B(\boldsymbol{x},r)$. Since this means that $v=v_{\mathrm i}=-\widetilde{b}_l$ in $B(\boldsymbol{x},r)\cap\Omega$, together with the fact that $v_{\mathrm i}$ is harmonic in $\Omega$, we have $v_{\mathrm i}=-\widetilde{b}_l$ in $\Omega$ by the analyticity of $v_{\mathrm i}$ in $\Omega$. Since $v=-\widetilde{b}_l$ on $\partial\Omega$, we have $v=-\widetilde{b}_l$ in ${\mathbb R}^3$. Hence, $-\Delta\widetilde{b}_l=0$ in ${\mathbb R}^3$, and thus, $P(D)\chi=0$ in $\Omega$, which is a contradiction.

